 "content": "def transform(grid):
    """Fill single-cell gaps between repeated non-background cells in each row."""
    out = [row[:] for row in grid]
    colors = {v for row in grid for v in row}
    # The enclosing field is the most frequent color; the marked pattern is another.
    bg = max(colors, key=lambda c: sum(row.count(c) for row in grid))
    marks = [c for c in colors if c != bg]
    if not marks:
        return out
    mark = max(marks, key=lambda c: sum(row.count(c) for row in grid))
    fill = 2
    for r, row in enumerate(grid):
        for c in range(1, len(row) - 1):
            if row[c] == bg and row[c-1] == mark and row[c+1] == mark:
                out[r][c] = fill
    return out
